import Foundation
@MainActor final class AdminDashboardViewModel:ObservableObject{@Published var userCount=0;@Published var medicalCount=0;@Published var productCount=0;@Published var isLoading=false;@Published var errorMessage:String?;func load(token:String?)async{guard !isLoading else{return};isLoading=true;defer{isLoading=false};do{let api=APIClient(token:token);async let u=api.users();async let m=api.medicals();async let p=api.products();userCount=(try await u).filter{$0.is_active==1}.count;medicalCount=try await m.count;productCount=try await p.count}catch{errorMessage=error.localizedDescription}}}